choose.when:
EXISTS (SELECT 1 FROM booking_grant g WHERE g.community_id = #{actor.communityId}
  AND g.elder_id = e.id AND g.family_id = #{actor.id} AND g.revoked = FALSE AND g.expires_at > #{now}
  AND g.can_book = TRUE)

mapper.select:
SELECT COUNT(*) FROM service_booking WHERE community_id = #{community} AND worker_id = #{worker}
  AND id != #{except} AND status IN ('CONFIRMED','IN_PROGRESS')
  AND scheduled_start < #{end} AND scheduled_end > #{start}
